    lease_mileage: { inputs: [['allowed', 'n', false], ['months', 'm', false], ['odometer', 'n', false], ['term', 'm', false], ['fee', '$', false]], out: ["Projected excess miles", (v) => Math.max(0, v.odometer / v.months * v.term - v.allowed * v.term / 12), 'n'], rows: [['r1', (v) => v.odometer / v.months * v.term, 'n'], ['r2', (v) => v.allowed * v.term / 12, 'n'], ['r3', (v) => Math.max(0, v.odometer / v.months * v.term - v.allowed * v.term / 12) * v.fee, '$']], src: "max(0, odometer ÷ months × term − allowed × term ÷ 12)" },
