    net_promoter_score: { inputs: [['promoters', 'i', false], ['passives', 'i', false], ['detractors', 'i', false]], out: ["Net Promoter Score", (v) => (v.promoters - v.detractors) / (v.promoters + v.passives + v.detractors) * 100, 'n'], rows: [['r1', (v) => v.promoters + v.passives + v.detractors, 'n']], src: "(promoters − detractors) ÷ (promoters + passives + detractors) × 100" },
