    tariff: { inputs: [['value', '$', false], ['tariff', '%', false], ['shipping', '$', false], ['fees', '$', false]], out: ["Landed cost", (v) => v.value + v.shipping + (v.value + v.shipping) * v.tariff + v.fees, '$'], rows: [['r1', (v) => (v.value + v.shipping) * v.tariff, '$'], ['r2', (v) => (v.value + v.shipping) * v.tariff / v.value, '%']], src: "value + shipping + (value + shipping) × tariff + fees" },
